def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    x = clip(rng.uniform(lb, ub, size=dim))
    best_x = x.copy()
    best_f = func(x)

    for _ in range(budget - 1):
        # Random search
        candidate = clip(rng.uniform(lb, ub, size=dim))

        # Calculate the probability of acceptance based on fitness improvement
        if func(candidate) < best_f:
            prob_accept = np.exp((best_f - func(candidate)) / (func(candidate) + 1e-8))
        else:
            prob_accept = 1.0

        # Accept or reject the candidate with probability prob_accept
        if rng.uniform(0, 1) < prob_accept:
            x = candidate.copy()
            best_x = x.copy()
            best_f = func(x)

        # Local exploration: perform a small step in the direction of the gradient
        grad = np.zeros(dim)
        for i in range(dim):
            eps = rng.uniform(-1e-6, 1e-6)
            grad[i] = (func(clip(x + eps * np.eye(dim)[i])) - func(clip(x - eps * np.eye(dim)[i]))) / (2.0 * eps)
        x += 0.01 * grad

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    N = int(np.sqrt(budget))
    best_x = None
    best_y = float('inf')

    for i in range(N):
        N_halving = int(budget / (i + 1))
        x_init = rng.uniform(lb, ub, size=(dim,))
        x_best_halving = x_init.copy()
        y_best_halving = func(x_best_halving)

        for _ in range(N_halving):
            x_random = clip(rng.normal(loc=x_best_halving, scale=0.1, size=(dim,)))
            y_random = func(x_random)
            if y_random < y_best_halving:
                x_best_halving = x_random
                y_best_halving = y_random

        if y_best_halving < best_y:
            best_x = x_best_halving.copy()
            best_y = y_best_halving

    return best_x
